        snapshot = {'sense_revision': sense.revision, 'definition': sense.editorial_definition,
                    'pronunciation_revision': pron.revision if pron else None, 'pronunciation': pron.editorial_value if pron else ''}
        Link.objects.using(alias).filter(pk=link.pk).update(editorial_snapshot=snapshot, selected_headword=link.evidence.headword)
        History.objects.using(alias).create(link_id=link.pk, revision=1, reason='继承旧关联：冻结迁移时选择，不逆推历史学习版本',
            selection={'sense_id': str(link.sense_id), 'pronunciation_id': str(link.pronunciation_id) if link.pronunciation_id else None,
                       'evidence_id': str(link.evidence_id), 'editorial_snapshot': snapshot, 'headword': link.evidence.headword,
                       'chinese_version_id': None, 'presentation_revision': 0})


